window.LESSON_DATA = {"schemaVersion":"1.0.0","version":"1.0.1","buildDate":"2026-07-29","course":"IB Mathematics: Applications and Interpretation SL","unit":{"number":1,"title":"Number and Algebra"},"lesson":{"number":"1.2","slug":"arithmetic-sequences","title":"Arithmetic Sequences and Series","subtitle":"Model constant additive change with recursive and explicit rules, then accumulate terms efficiently.","syllabus_focus":"SL 1.2 — Arithmetic sequences and series; use of formulae for the nth term and sum of the first n terms; applications.","skill_keys":["IBAI.U1.SEQUENCES","IBAI.U1.MODELING"],"objectives":["Recognize constant first difference as arithmetic structure.","Move between recursive, explicit, tabular and contextual representations.","Find any term and the sum of the first n terms.","Interpret parameters and validate arithmetic models in context."],"vocab":["sequence","term","first term","common difference","recursive rule","explicit rule","series","partial sum"],"technology":"Use sequence and spreadsheet modes to generate terms and cumulative sums. Verify the calculator output by checking the first term and one difference.","transition":"Arithmetic sequences and series remain part of the updated course."},"slides":[{"section":"Launch","title":"1.2 · Arithmetic Sequences and Series","html":"<div class=\"cover-grid\"><div><div class=\"cover-kicker\">IB DP Mathematics · Applications and Interpretation SL</div><h1><span class=\"cover-number\">1.2</span>Arithmetic Sequences and Series</h1><p class=\"cover-subtitle\">Model constant additive change with recursive and explicit rules, then accumulate terms efficiently.</p><div class=\"pill-row\"><span>Current syllabus</span><span>Technology-rich</span><span>Modelling</span><span>Original practice</span></div></div><svg class=\"concept-visual\" viewBox=\"0 0 520 180\" role=\"img\" aria-label=\"Arithmetic sequence bars\"><rect width=\"520\" height=\"180\" rx=\"22\" fill=\"#F4EFE8\"/><text x=\"28\" y=\"32\" font-weight=\"800\" fill=\"#17324D\">Constant additive change</text><rect x=\"55\" y=\"100\" width=\"38\" height=\"35\" rx=\"7\" fill=\"#7A1733\" opacity=\".88\"/><text x=\"74\" y=\"154\" text-anchor=\"middle\">1</text><rect x=\"120\" y=\"88\" width=\"38\" height=\"47\" rx=\"7\" fill=\"#17324D\" opacity=\".88\"/><text x=\"139\" y=\"154\" text-anchor=\"middle\">2</text><rect x=\"185\" y=\"76\" width=\"38\" height=\"59\" rx=\"7\" fill=\"#177E89\" opacity=\".88\"/><text x=\"204\" y=\"154\" text-anchor=\"middle\">3</text><rect x=\"250\" y=\"64\" width=\"38\" height=\"71\" rx=\"7\" fill=\"#D4A72C\" opacity=\".88\"/><text x=\"269\" y=\"154\" text-anchor=\"middle\">4</text><rect x=\"315\" y=\"52\" width=\"38\" height=\"83\" rx=\"7\" fill=\"#7A1733\" opacity=\".88\"/><text x=\"334\" y=\"154\" text-anchor=\"middle\">5</text><rect x=\"380\" y=\"40\" width=\"38\" height=\"95\" rx=\"7\" fill=\"#17324D\" opacity=\".88\"/><text x=\"399\" y=\"154\" text-anchor=\"middle\">6</text><path d=\"M74 98 L399 38\" stroke=\"#177E89\" stroke-width=\"4\" fill=\"none\"/><text x=\"430\" y=\"48\" fill=\"#7A1733\">+d each step</text></svg></div>","kind":"cover","eyebrow":"Unit 1 · Number and Algebra"},{"section":"Launch","title":"Your place in Unit 1","html":"<div class=\"unit-map\"><div class=\"map-node \"><b>1.1</b><span>Scientific Notation and Orders of Magnitude</span></div><div class=\"map-node active\"><b>1.2</b><span>Arithmetic Sequences and Series</span></div><div class=\"map-node \"><b>1.3</b><span>Geometric Sequences and Series</span></div><div class=\"map-node \"><b>1.4</b><span>Financial Applications of Sequences</span></div><div class=\"map-node \"><b>1.5</b><span>Introduction to Logarithms</span></div><div class=\"map-node \"><b>1.6</b><span>Approximation, Bounds and Percentage Error</span></div><div class=\"map-node \"><b>1.7</b><span>Loans, Annuities and Amortization</span></div><div class=\"map-node \"><b>1.8</b><span>Technology for Equations and Systems</span></div></div><p class=\"callout\">The course moves from representation and discrete change to financial modelling, uncertainty and technology-based solution methods.</p>","kind":"content","eyebrow":""},{"section":"Launch","title":"Syllabus focus","html":"<div class=\"focus-card\"><h3>Current course alignment</h3><p>SL 1.2 — Arithmetic sequences and series; use of formulae for the nth term and sum of the first n terms; applications.</p><p><b>Platform mastery keys:</b> IBAI.U1.SEQUENCES, IBAI.U1.MODELING</p></div><div class=\"transition-note\">Arithmetic sequences and series remain part of the updated course.</div>","kind":"content","eyebrow":""},{"section":"Inquiry","title":"A question worth investigating","html":"<blockquote>When does a constant amount of change produce a useful model—and when does it fail?</blockquote><p>Record an initial response. Return to it at the end and identify how your reasoning changed.</p><textarea class=\"student-note\" data-note=\"inquiry\" aria-label=\"Inquiry response\"></textarea>","kind":"inquiry","eyebrow":""},{"section":"Inquiry","title":"Learning intentions","html":"<div class=\"two-col\"><div><h3>By the end, you can…</h3><ul class=\"check-list\"><li>Recognize constant first difference as arithmetic structure.</li><li>Move between recursive, explicit, tabular and contextual representations.</li><li>Find any term and the sum of the first n terms.</li><li>Interpret parameters and validate arithmetic models in context.</li></ul></div><div><h3>Evidence of understanding</h3><ul class=\"check-list\"><li>Choose an efficient representation.</li><li>Use technology transparently.</li><li>Interpret rather than merely calculate.</li><li>Evaluate assumptions and precision.</li></ul></div></div>","kind":"content","eyebrow":""},{"section":"Diagnostic","title":"Prior-knowledge diagnostic","html":"<div class=\"student-turn\"><h3>Try before instruction</h3><p>The values \\(18,25,32,39,\\ldots\\) are recorded at equal time intervals. What remains constant, and what would the tenth value be?</p><textarea class=\"student-note\" data-note=\"diagnostic\"></textarea><details><summary>Diagnostic lens</summary><p>Focus on structure, units and the meaning of the result—not just a final number.</p></details></div>","kind":"student","eyebrow":""},{"section":"Language","title":"Core vocabulary","html":"<div class=\"vocab-grid\"><div class=\"vocab-chip\">sequence</div><div class=\"vocab-chip\">term</div><div class=\"vocab-chip\">first term</div><div class=\"vocab-chip\">common difference</div><div class=\"vocab-chip\">recursive rule</div><div class=\"vocab-chip\">explicit rule</div><div class=\"vocab-chip\">series</div><div class=\"vocab-chip\">partial sum</div></div><p class=\"callout\">Use precise vocabulary in every explanation. In IB mathematics, communication earns meaning, not decoration.</p>","kind":"content","eyebrow":""},{"section":"Approach","title":"The AI modelling cycle","html":"<div class=\"cycle\"><div>Context</div><span>→</span><div>Assumptions</div><span>→</span><div>Mathematical form</div><span>→</span><div>Technology & computation</div><span>→</span><div>Interpretation</div><span>→</span><div>Validation & refinement</div></div><p>Every substantial task in this lesson returns to this cycle. A numerical answer without interpretation is unfinished.</p>","kind":"content","eyebrow":""},{"section":"Concept 1","title":"Constant additive change","html":"<div class=\"concept-grid\"><div><p>An arithmetic sequence changes by the same amount between consecutive terms. The common difference may be positive, negative or zero.</p><div class=\"formula-panel\">\\[d=u_{n+1}-u_n\\]</div></div><svg class=\"concept-visual\" viewBox=\"0 0 520 180\" role=\"img\" aria-label=\"Arithmetic sequence bars\"><rect width=\"520\" height=\"180\" rx=\"22\" fill=\"#F4EFE8\"/><text x=\"28\" y=\"32\" font-weight=\"800\" fill=\"#17324D\">Constant additive change</text><rect x=\"55\" y=\"100\" width=\"38\" height=\"35\" rx=\"7\" fill=\"#7A1733\" opacity=\".88\"/><text x=\"74\" y=\"154\" text-anchor=\"middle\">1</text><rect x=\"120\" y=\"88\" width=\"38\" height=\"47\" rx=\"7\" fill=\"#17324D\" opacity=\".88\"/><text x=\"139\" y=\"154\" text-anchor=\"middle\">2</text><rect x=\"185\" y=\"76\" width=\"38\" height=\"59\" rx=\"7\" fill=\"#177E89\" opacity=\".88\"/><text x=\"204\" y=\"154\" text-anchor=\"middle\">3</text><rect x=\"250\" y=\"64\" width=\"38\" height=\"71\" rx=\"7\" fill=\"#D4A72C\" opacity=\".88\"/><text x=\"269\" y=\"154\" text-anchor=\"middle\">4</text><rect x=\"315\" y=\"52\" width=\"38\" height=\"83\" rx=\"7\" fill=\"#7A1733\" opacity=\".88\"/><text x=\"334\" y=\"154\" text-anchor=\"middle\">5</text><rect x=\"380\" y=\"40\" width=\"38\" height=\"95\" rx=\"7\" fill=\"#17324D\" opacity=\".88\"/><text x=\"399\" y=\"154\" text-anchor=\"middle\">6</text><path d=\"M74 98 L399 38\" stroke=\"#177E89\" stroke-width=\"4\" fill=\"none\"/><text x=\"430\" y=\"48\" fill=\"#7A1733\">+d each step</text></svg></div>","kind":"content","eyebrow":"Concept cycle 1 of 5"},{"section":"Concept 1","title":"Worked example · Constant additive change","html":"<div class=\"worked\"><div class=\"prompt\"><span>Problem</span><p>Show that \\(14,9,4,-1,\\ldots\\) is arithmetic.</p></div><div class=\"method\"><span>Reasoning</span><p>Each difference is \\(-5\\), so \\(d=-5\\).</p></div></div>","kind":"worked","eyebrow":""},{"section":"Concept 1","title":"Student turn","html":"<div class=\"student-turn\"><h3>Now transfer the idea</h3><p>Find the common difference of \\(3.6,4.25,4.9,\\ldots\\).</p><textarea class=\"student-note\" data-note=\"turn-1\"></textarea><details><summary>Reveal answer and check</summary><p>\\(d=0.65\\).</p></details></div>","kind":"student","eyebrow":""},{"section":"Concept 1","title":"Explain the solution","html":"<div class=\"solution-panel\"><h3>Complete reasoning</h3><p>\\(d=0.65\\).</p><div class=\"explain-prompt\">Which representation, formula or technology step made the solution efficient?</div></div>","kind":"solution","eyebrow":""},{"section":"Concept 1","title":"Misconception clinic","html":"<div class=\"misconception\"><div class=\"warning-symbol\">!</div><div><h3>Common trap</h3><p>A sequence can be arithmetic while decreasing; the difference need not be positive.</p><p><b>Repair move:</b> test the claim with a simple value, units, substitution or a graph.</p></div></div>","kind":"misconception","eyebrow":""},{"section":"Concept 2","title":"The nth term","html":"<div class=\"concept-grid\"><div><p>Start at \\(u_1=a\\). Reaching term \\(n\\) requires \\(n-1\\) equal jumps of size \\(d\\).</p><div class=\"formula-panel\">\\[u_n=a+(n-1)d\\]</div></div><svg class=\"concept-visual\" viewBox=\"0 0 520 180\" role=\"img\" aria-label=\"Arithmetic sequence bars\"><rect width=\"520\" height=\"180\" rx=\"22\" fill=\"#F4EFE8\"/><text x=\"28\" y=\"32\" font-weight=\"800\" fill=\"#17324D\">Constant additive change</text><rect x=\"55\" y=\"100\" width=\"38\" height=\"35\" rx=\"7\" fill=\"#7A1733\" opacity=\".88\"/><text x=\"74\" y=\"154\" text-anchor=\"middle\">1</text><rect x=\"120\" y=\"88\" width=\"38\" height=\"47\" rx=\"7\" fill=\"#17324D\" opacity=\".88\"/><text x=\"139\" y=\"154\" text-anchor=\"middle\">2</text><rect x=\"185\" y=\"76\" width=\"38\" height=\"59\" rx=\"7\" fill=\"#177E89\" opacity=\".88\"/><text x=\"204\" y=\"154\" text-anchor=\"middle\">3</text><rect x=\"250\" y=\"64\" width=\"38\" height=\"71\" rx=\"7\" fill=\"#D4A72C\" opacity=\".88\"/><text x=\"269\" y=\"154\" text-anchor=\"middle\">4</text><rect x=\"315\" y=\"52\" width=\"38\" height=\"83\" rx=\"7\" fill=\"#7A1733\" opacity=\".88\"/><text x=\"334\" y=\"154\" text-anchor=\"middle\">5</text><rect x=\"380\" y=\"40\" width=\"38\" height=\"95\" rx=\"7\" fill=\"#17324D\" opacity=\".88\"/><text x=\"399\" y=\"154\" text-anchor=\"middle\">6</text><path d=\"M74 98 L399 38\" stroke=\"#177E89\" stroke-width=\"4\" fill=\"none\"/><text x=\"430\" y=\"48\" fill=\"#7A1733\">+d each step</text></svg></div>","kind":"content","eyebrow":"Concept cycle 2 of 5"},{"section":"Concept 2","title":"Worked example · The nth term","html":"<div class=\"worked\"><div class=\"prompt\"><span>Problem</span><p>Find \\(u_{30}\\) for \\(a=11\\), \\(d=4\\).</p></div><div class=\"method\"><span>Reasoning</span><p>\\(u_{30}=11+29(4)=127\\).</p></div></div>","kind":"worked","eyebrow":""},{"section":"Concept 2","title":"Student turn","html":"<div class=\"student-turn\"><h3>Now transfer the idea</h3><p>For \\(a=52\\), \\(d=-3\\), find \\(u_{18}\\).</p><textarea class=\"student-note\" data-note=\"turn-2\"></textarea><details><summary>Reveal answer and check</summary><p>\\(u_{18}=1\\).</p></details></div>","kind":"student","eyebrow":""},{"section":"Concept 2","title":"Explain the solution","html":"<div class=\"solution-panel\"><h3>Complete reasoning</h3><p>\\(u_{18}=1\\).</p><div class=\"explain-prompt\">Which representation, formula or technology step made the solution efficient?</div></div>","kind":"solution","eyebrow":""},{"section":"Concept 2","title":"Misconception clinic","html":"<div class=\"misconception\"><div class=\"warning-symbol\">!</div><div><h3>Common trap</h3><p>Use \\(n-1\\), not \\(n\\): there are no jumps before the first term.</p><p><b>Repair move:</b> test the claim with a simple value, units, substitution or a graph.</p></div></div>","kind":"misconception","eyebrow":""},{"section":"Concept 3","title":"Recovering a model","html":"<div class=\"concept-grid\"><div><p>Two known terms produce two linear equations in \\(a\\) and \\(d\\). Subtracting eliminates \\(a\\).</p><div class=\"formula-panel\">\\[u_p=a+(p-1)d,\\qquad u_q=a+(q-1)d\\]</div></div><svg class=\"concept-visual\" viewBox=\"0 0 520 180\" role=\"img\" aria-label=\"Arithmetic sequence bars\"><rect width=\"520\" height=\"180\" rx=\"22\" fill=\"#F4EFE8\"/><text x=\"28\" y=\"32\" font-weight=\"800\" fill=\"#17324D\">Constant additive change</text><rect x=\"55\" y=\"100\" width=\"38\" height=\"35\" rx=\"7\" fill=\"#7A1733\" opacity=\".88\"/><text x=\"74\" y=\"154\" text-anchor=\"middle\">1</text><rect x=\"120\" y=\"88\" width=\"38\" height=\"47\" rx=\"7\" fill=\"#17324D\" opacity=\".88\"/><text x=\"139\" y=\"154\" text-anchor=\"middle\">2</text><rect x=\"185\" y=\"76\" width=\"38\" height=\"59\" rx=\"7\" fill=\"#177E89\" opacity=\".88\"/><text x=\"204\" y=\"154\" text-anchor=\"middle\">3</text><rect x=\"250\" y=\"64\" width=\"38\" height=\"71\" rx=\"7\" fill=\"#D4A72C\" opacity=\".88\"/><text x=\"269\" y=\"154\" text-anchor=\"middle\">4</text><rect x=\"315\" y=\"52\" width=\"38\" height=\"83\" rx=\"7\" fill=\"#7A1733\" opacity=\".88\"/><text x=\"334\" y=\"154\" text-anchor=\"middle\">5</text><rect x=\"380\" y=\"40\" width=\"38\" height=\"95\" rx=\"7\" fill=\"#17324D\" opacity=\".88\"/><text x=\"399\" y=\"154\" text-anchor=\"middle\">6</text><path d=\"M74 98 L399 38\" stroke=\"#177E89\" stroke-width=\"4\" fill=\"none\"/><text x=\"430\" y=\"48\" fill=\"#7A1733\">+d each step</text></svg></div>","kind":"content","eyebrow":"Concept cycle 3 of 5"},{"section":"Concept 3","title":"Worked example · Recovering a model","html":"<div class=\"worked\"><div class=\"prompt\"><span>Problem</span><p>Given \\(u_5=26\\) and \\(u_{12}=61\\), find \\(a,d\\).</p></div><div class=\"method\"><span>Reasoning</span><p>\\(7d=35\\Rightarrow d=5\\), then \\(a+4(5)=26\\Rightarrow a=6\\).</p></div></div>","kind":"worked","eyebrow":""},{"section":"Concept 3","title":"Student turn","html":"<div class=\"student-turn\"><h3>Now transfer the idea</h3><p>Given \\(u_4=19\\) and \\(u_{10}=43\\), find \\(u_1\\).</p><textarea class=\"student-note\" data-note=\"turn-3\"></textarea><details><summary>Reveal answer and check</summary><p>\\(6d=24\\Rightarrow d=4\\), so \\(a=7\\).</p></details></div>","kind":"student","eyebrow":""},{"section":"Concept 3","title":"Explain the solution","html":"<div class=\"solution-panel\"><h3>Complete reasoning</h3><p>\\(6d=24\\Rightarrow d=4\\), so \\(a=7\\).</p><div class=\"explain-prompt\">Which representation, formula or technology step made the solution efficient?</div></div>","kind":"solution","eyebrow":""},{"section":"Concept 3","title":"Misconception clinic","html":"<div class=\"misconception\"><div class=\"warning-symbol\">!</div><div><h3>Common trap</h3><p>The subscript is an index, not a multiplier.</p><p><b>Repair move:</b> test the claim with a simple value, units, substitution or a graph.</p></div></div>","kind":"misconception","eyebrow":""},{"section":"Concept 4","title":"Arithmetic series","html":"<div class=\"concept-grid\"><div><p>A series is a sum of sequence terms. Pairing first and last terms explains both standard sum formulae.</p><div class=\"formula-panel\">\\[S_n=\\frac n2[2a+(n-1)d]=\\frac n2(a+u_n)\\]</div></div><svg class=\"concept-visual\" viewBox=\"0 0 520 180\" role=\"img\" aria-label=\"Arithmetic sequence bars\"><rect width=\"520\" height=\"180\" rx=\"22\" fill=\"#F4EFE8\"/><text x=\"28\" y=\"32\" font-weight=\"800\" fill=\"#17324D\">Constant additive change</text><rect x=\"55\" y=\"100\" width=\"38\" height=\"35\" rx=\"7\" fill=\"#7A1733\" opacity=\".88\"/><text x=\"74\" y=\"154\" text-anchor=\"middle\">1</text><rect x=\"120\" y=\"88\" width=\"38\" height=\"47\" rx=\"7\" fill=\"#17324D\" opacity=\".88\"/><text x=\"139\" y=\"154\" text-anchor=\"middle\">2</text><rect x=\"185\" y=\"76\" width=\"38\" height=\"59\" rx=\"7\" fill=\"#177E89\" opacity=\".88\"/><text x=\"204\" y=\"154\" text-anchor=\"middle\">3</text><rect x=\"250\" y=\"64\" width=\"38\" height=\"71\" rx=\"7\" fill=\"#D4A72C\" opacity=\".88\"/><text x=\"269\" y=\"154\" text-anchor=\"middle\">4</text><rect x=\"315\" y=\"52\" width=\"38\" height=\"83\" rx=\"7\" fill=\"#7A1733\" opacity=\".88\"/><text x=\"334\" y=\"154\" text-anchor=\"middle\">5</text><rect x=\"380\" y=\"40\" width=\"38\" height=\"95\" rx=\"7\" fill=\"#17324D\" opacity=\".88\"/><text x=\"399\" y=\"154\" text-anchor=\"middle\">6</text><path d=\"M74 98 L399 38\" stroke=\"#177E89\" stroke-width=\"4\" fill=\"none\"/><text x=\"430\" y=\"48\" fill=\"#7A1733\">+d each step</text></svg></div>","kind":"content","eyebrow":"Concept cycle 4 of 5"},{"section":"Concept 4","title":"Worked example · Arithmetic series","html":"<div class=\"worked\"><div class=\"prompt\"><span>Problem</span><p>Find \\(S_{25}\\) for \\(a=8,d=3\\).</p></div><div class=\"method\"><span>Reasoning</span><p>\\(u_{25}=80\\), so \\(S_{25}=\\frac{25}{2}(8+80)=1100\\).</p></div></div>","kind":"worked","eyebrow":""},{"section":"Concept 4","title":"Student turn","html":"<div class=\"student-turn\"><h3>Now transfer the idea</h3><p>Find \\(S_{40}\\) for \\(a=120,d=-2\\).</p><textarea class=\"student-note\" data-note=\"turn-4\"></textarea><details><summary>Reveal answer and check</summary><p>\\(u_{40}=42\\), so \\(S_{40}=20(162)=3240\\).</p></details></div>","kind":"student","eyebrow":""},{"section":"Concept 4","title":"Explain the solution","html":"<div class=\"solution-panel\"><h3>Complete reasoning</h3><p>\\(u_{40}=42\\), so \\(S_{40}=20(162)=3240\\).</p><div class=\"explain-prompt\">Which representation, formula or technology step made the solution efficient?</div></div>","kind":"solution","eyebrow":""},{"section":"Concept 4","title":"Misconception clinic","html":"<div class=\"misconception\"><div class=\"warning-symbol\">!</div><div><h3>Common trap</h3><p>Do not use \\(u_n\\) as though it were the sum; a term and a partial sum answer different questions.</p><p><b>Repair move:</b> test the claim with a simple value, units, substitution or a graph.</p></div></div>","kind":"misconception","eyebrow":""},{"section":"Concept 5","title":"Modelling and restrictions","html":"<div class=\"concept-grid\"><div><p>Arithmetic models fit situations with approximately constant additive change. State units, define the index, and restrict the model to a defensible domain.</p><div class=\"formula-panel\">\\[\\text{quantity at stage }n=\\text{initial quantity}+(n-1)(\\text{change per stage})\\]</div></div><svg class=\"concept-visual\" viewBox=\"0 0 520 180\" role=\"img\" aria-label=\"Arithmetic sequence bars\"><rect width=\"520\" height=\"180\" rx=\"22\" fill=\"#F4EFE8\"/><text x=\"28\" y=\"32\" font-weight=\"800\" fill=\"#17324D\">Constant additive change</text><rect x=\"55\" y=\"100\" width=\"38\" height=\"35\" rx=\"7\" fill=\"#7A1733\" opacity=\".88\"/><text x=\"74\" y=\"154\" text-anchor=\"middle\">1</text><rect x=\"120\" y=\"88\" width=\"38\" height=\"47\" rx=\"7\" fill=\"#17324D\" opacity=\".88\"/><text x=\"139\" y=\"154\" text-anchor=\"middle\">2</text><rect x=\"185\" y=\"76\" width=\"38\" height=\"59\" rx=\"7\" fill=\"#177E89\" opacity=\".88\"/><text x=\"204\" y=\"154\" text-anchor=\"middle\">3</text><rect x=\"250\" y=\"64\" width=\"38\" height=\"71\" rx=\"7\" fill=\"#D4A72C\" opacity=\".88\"/><text x=\"269\" y=\"154\" text-anchor=\"middle\">4</text><rect x=\"315\" y=\"52\" width=\"38\" height=\"83\" rx=\"7\" fill=\"#7A1733\" opacity=\".88\"/><text x=\"334\" y=\"154\" text-anchor=\"middle\">5</text><rect x=\"380\" y=\"40\" width=\"38\" height=\"95\" rx=\"7\" fill=\"#17324D\" opacity=\".88\"/><text x=\"399\" y=\"154\" text-anchor=\"middle\">6</text><path d=\"M74 98 L399 38\" stroke=\"#177E89\" stroke-width=\"4\" fill=\"none\"/><text x=\"430\" y=\"48\" fill=\"#7A1733\">+d each step</text></svg></div>","kind":"content","eyebrow":"Concept cycle 5 of 5"},{"section":"Concept 5","title":"Worked example · Modelling and restrictions","html":"<div class=\"worked\"><div class=\"prompt\"><span>Problem</span><p>A venue has 22 seats in row 1 and 3 more seats in each later row. Find seats in row 18 and total seats.</p></div><div class=\"method\"><span>Reasoning</span><p>\\(u_{18}=73\\), and \\(S_{18}=855\\).</p></div></div>","kind":"worked","eyebrow":""},{"section":"Concept 5","title":"Student turn","html":"<div class=\"student-turn\"><h3>Now transfer the idea</h3><p>A tank loses 7 L each minute from 350 L. Model the amount after \\(n\\) minutes if \\(n=0\\) is the start.</p><textarea class=\"student-note\" data-note=\"turn-5\"></textarea><details><summary>Reveal answer and check</summary><p>\\(V_n=350-7n\\), valid until the amount reaches zero.</p></details></div>","kind":"student","eyebrow":""},{"section":"Concept 5","title":"Explain the solution","html":"<div class=\"solution-panel\"><h3>Complete reasoning</h3><p>\\(V_n=350-7n\\), valid until the amount reaches zero.</p><div class=\"explain-prompt\">Which representation, formula or technology step made the solution efficient?</div></div>","kind":"solution","eyebrow":""},{"section":"Concept 5","title":"Misconception clinic","html":"<div class=\"misconception\"><div class=\"warning-symbol\">!</div><div><h3>Common trap</h3><p>Context may begin at time 0, while the textbook formula often labels the first term with index 1. Define the index explicitly.</p><p><b>Repair move:</b> test the claim with a simple value, units, substitution or a graph.</p></div></div>","kind":"misconception","eyebrow":""},{"section":"Technology","title":"Interactive exploration","html":"<div id=\"lesson-lab\" class=\"lab\" data-lab=\"1.2\"></div><p class=\"lab-note\">Change more than one input. Predict before pressing calculate, then explain what stays invariant.</p>","kind":"lab","eyebrow":""},{"section":"Technology","title":"Transparent technology workflow","html":"<div class=\"workflow\"><div><b>1</b> Define variables and domain</div><div><b>2</b> Enter the mathematical model</div><div><b>3</b> Choose an appropriate tool</div><div><b>4</b> Record settings/output</div><div><b>5</b> Verify independently</div><div><b>6</b> Interpret and round</div></div><p>Use sequence and spreadsheet modes to generate terms and cumulative sums. Verify the calculator output by checking the first term and one difference.</p>","kind":"content","eyebrow":""},{"section":"Application","title":"Global and local context","html":"<div class=\"context-card\"><span>Context challenge</span><p>Design a stepped seating plan for an ECHS event. Balance visibility, capacity and space while explaining why an arithmetic model is appropriate.</p></div><textarea class=\"student-note tall\" data-note=\"context\"></textarea>","kind":"student","eyebrow":""},{"section":"Inquiry","title":"Mini-investigation","html":"<div class=\"investigation\"><h3>Question → evidence → conclusion</h3><p>Collect a real pattern with approximately constant additive change. Fit an arithmetic model, quantify residuals, and identify when the model becomes unrealistic.</p><ul class=\"check-list\"><li>State the question and variables.</li><li>Record assumptions and data sources.</li><li>Show mathematics and technology output.</li><li>Interpret, evaluate and refine.</li></ul></div>","kind":"investigation","eyebrow":""},{"section":"Assessment","title":"IB command terms","html":"<div class=\"command-grid\"><div><b>Write down</b><span>Give the result with little or no working.</span></div><div><b>Calculate</b><span>Show enough method for the result to be reproducible.</span></div><div><b>Determine</b><span>Reach a result with supporting reasoning.</span></div><div><b>Explain</b><span>Give causes, mechanisms or mathematical meaning.</span></div><div><b>Interpret</b><span>Translate mathematics back into context.</span></div><div><b>Comment</b><span>Make a judgement supported by evidence.</span></div></div>","kind":"content","eyebrow":""},{"section":"Assessment","title":"Auditorium seating","html":"<div class=\"task-preview\"><div class=\"task-meta\"><span>Paper 1-style short response</span><span>9 marks</span><span>GDC expected</span></div><h3>Auditorium seating</h3><p>An auditorium has 28 seats in the first row and 3 additional seats in every later row. There are 24 rows.</p><div class=\"task-part\"><b>(a)</b> Write a formula for the number of seats in row \\(n\\). <span class=\"marks\">[2]</span></div><div class=\"task-part\"><b>(b)</b> Find the number of seats in the final row. <span class=\"marks\">[2]</span></div><div class=\"task-part\"><b>(c)</b> Find the total number of seats. <span class=\"marks\">[3]</span></div><div class=\"task-part\"><b>(d)</b> The design allows at most 1600 seats. State whether one additional row following the pattern is possible. Justify. <span class=\"marks\">[2]</span></div></div>","kind":"exam","eyebrow":""},{"section":"Assessment","title":"Auditorium seating · markscheme","html":"<div class=\"task-preview solution-preview\"><h3>Auditorium seating — worked markscheme</h3><div class=\"solution-part\"><b>(a) \\(u_n=28+3(n-1)=3n+25\\)</b><p>M1 arithmetic nth-term structure; A1 simplified/equivalent formula.</p></div><div class=\"solution-part\"><b>(b) 97</b><p>M1 substitutes \\(n=24\\); A1 97.</p></div><div class=\"solution-part\"><b>(c) 1500</b><p>M1 uses arithmetic sum; M1 substitutes endpoints; A1 1500.</p></div><div class=\"solution-part\"><b>(d) Yes. Row 25 has 100 seats, so the new total is exactly 1600.</b><p>M1 computes row 25 or the new total; A1 concludes that equality is allowed by “at most”.</p></div></div>","kind":"solution","eyebrow":""},{"section":"Assessment","title":"Water-tank monitoring","html":"<div class=\"task-preview\"><div class=\"task-meta\"><span>Paper 2-style extended response</span><span>11 marks</span><span>GDC expected</span></div><h3>Water-tank monitoring</h3><p>At time \\(t=0\\), a tank contains 920 L. During a controlled release it loses 17 L each minute.</p><div class=\"task-part\"><b>(a)</b> Write a model for volume \\(V_t\\) after \\(t\\) minutes. <span class=\"marks\">[2]</span></div><div class=\"task-part\"><b>(b)</b> Find the volume after 31 minutes. <span class=\"marks\">[2]</span></div><div class=\"task-part\"><b>(c)</b> Find the first whole minute at which the volume is below 250 L. <span class=\"marks\">[3]</span></div><div class=\"task-part\"><b>(d)</b> Find the total amount recorded if readings at minutes 0 through 20 are added. <span class=\"marks\">[3]</span></div><div class=\"task-part\"><b>(e)</b> State one reason the linear model cannot continue indefinitely. <span class=\"marks\">[1]</span></div></div>","kind":"exam","eyebrow":""},{"section":"Assessment","title":"Water-tank monitoring · markscheme","html":"<div class=\"task-preview solution-preview\"><h3>Water-tank monitoring — worked markscheme</h3><div class=\"solution-part\"><b>(a) \\(V_t=920-17t\\)</b><p>M1 identifies constant decrease; A1 model with correct initial indexing.</p></div><div class=\"solution-part\"><b>(b) 393 L</b><p>M1 substitutes 31; A1 393.</p></div><div class=\"solution-part\"><b>(c) 40 minutes</b><p>M1 solves \\(920-17t<250\\); A1 threshold \\(t>39.411...\\); A1 first integer 40.</p></div><div class=\"solution-part\"><b>(d) 15,750 L</b><p>M1 recognizes 21 terms; M1 uses endpoints 920 and 580; A1 \\(21(1500)/2=15750\\).</p></div><div class=\"solution-part\"><b>(e) It eventually predicts negative volume or ignores changing flow conditions.</b><p>A1 relevant limitation.</p></div></div>","kind":"solution","eyebrow":""},{"section":"Connections","title":"Where this mathematics connects","html":"<div class=\"connection-grid\"><div>Linear functions</div><div>Discrete modelling</div><div>Finite differences</div><div>Budget and capacity planning</div></div><p>Write one sentence describing a connection you did not see at the start.</p><textarea class=\"student-note\" data-note=\"connection\"></textarea>","kind":"content","eyebrow":""},{"section":"Synthesis","title":"Five ideas to retain","html":"<ul class=\"check-list\"><li>Constant additive change: An arithmetic sequence changes by the same amount between consecutive terms.</li><li>The nth term: Start at \\(u_1=a\\).</li><li>Recovering a model: Two known terms produce two linear equations in \\(a\\) and \\(d\\).</li><li>Arithmetic series: A series is a sum of sequence terms.</li><li>Modelling and restrictions: Arithmetic models fit situations with approximately constant additive change.</li></ul>","kind":"summary","eyebrow":""},{"section":"Reflection","title":"Return to the inquiry question","html":"<blockquote>When does a constant amount of change produce a useful model—and when does it fail?</blockquote><textarea class=\"student-note tall\" data-note=\"reflection\"></textarea><div class=\"reflection-grid\"><label><input type=\"checkbox\" data-reflect=\"model\"> I can model</label><label><input type=\"checkbox\" data-reflect=\"calculate\"> I can calculate</label><label><input type=\"checkbox\" data-reflect=\"interpret\"> I can interpret</label><label><input type=\"checkbox\" data-reflect=\"evaluate\"> I can evaluate</label></div>","kind":"reflection","eyebrow":""},{"section":"Exit","title":"Exit ticket","html":"<div class=\"exit-grid\"><div><b>One calculation</b><p>Create and solve a new example using today’s central formula.</p></div><div><b>One explanation</b><p>Describe a common error and how to detect it.</p></div><div><b>One evaluation</b><p>State one assumption that could change a conclusion.</p></div></div><textarea class=\"student-note tall\" data-note=\"exit\"></textarea>","kind":"student","eyebrow":""},{"section":"Next","title":"Practice Studio","html":"<div class=\"launch-panel\"><h2>40 original questions</h2><p>Four levels: Foundation, Application, Reasoning and Challenge. Every item includes marks, calculator guidance, hints and a complete solution.</p><button class=\"route-jump\" data-go=\"practice\">Open Practice Studio</button></div>","kind":"launch","eyebrow":""},{"section":"Next","title":"Independent timed quiz","html":"<div class=\"launch-panel\"><h2>10 fresh questions</h2><p>Complete the quiz under a suggested 25-minute timer, then review explanations and update your mastery reflection.</p><button class=\"route-jump\" data-go=\"quiz\">Start timed quiz</button></div>","kind":"launch","eyebrow":""},{"section":"Next","title":"Authenticated question-bank bridge","html":"<div class=\"bank-bridge\"><h2>More practice on the platform</h2><p>This lesson maps to <code>IBAI.U1.SEQUENCES, IBAI.U1.MODELING</code>. The attached private banks stay inside authenticated school access; no private prompt is copied into this public lesson file.</p><a href=\"https://2ed944-cloud.github.io/ECHS-Math/question-bank/practice.html?course=ib-math-ai&unit=1&lesson=1.2\" class=\"button-link\">Open additional bank practice</a></div>","kind":"launch","eyebrow":""}],"practice":[{"id":"IBAI-1.2-P01","level":"Foundation","prompt":"For an arithmetic sequence with \\(u_1=7\\) and \\(d=3\\), find \\(u_{12}\\).","answer":"\\(40\\)","solution":"Use \\(u_n=a+(n-1)d\\): \\(7+(12-1)(3)=40\\).","marks":2,"calculator":"Mental / GDC check","command":"Calculate","hint":"","tags":["nth term"],"check":{"mode":"number","value":40,"tolerance":1e-06}},{"id":"IBAI-1.2-P02","level":"Foundation","prompt":"For an arithmetic sequence with \\(u_1=20\\) and \\(d=-2\\), find \\(u_{15}\\).","answer":"\\(-8\\)","solution":"Use \\(u_n=a+(n-1)d\\): \\(20+(15-1)(-2)=-8\\).","marks":2,"calculator":"Mental / GDC check","command":"Calculate","hint":"","tags":["nth term"],"check":{"mode":"number","value":-8,"tolerance":1e-06}},{"id":"IBAI-1.2-P03","level":"Foundation","prompt":"For an arithmetic sequence with \\(u_1=-5\\) and \\(d=4\\), find \\(u_{18}\\).","answer":"\\(63\\)","solution":"Use \\(u_n=a+(n-1)d\\): \\(-5+(18-1)(4)=63\\).","marks":2,"calculator":"Mental / GDC check","command":"Calculate","hint":"","tags":["nth term"],"check":{"mode":"number","value":63,"tolerance":1e-06}},{"id":"IBAI-1.2-P04","level":"Foundation","prompt":"For an arithmetic sequence with \\(u_1=3.5\\) and \\(d=0.75\\), find \\(u_{9}\\).","answer":"\\(9.5\\)","solution":"Use \\(u_n=a+(n-1)d\\): \\(3.5+(9-1)(0.75)=9.5\\).","marks":2,"calculator":"Mental / GDC check","command":"Calculate","hint":"","tags":["nth term"],"check":{"mode":"number","value":9.5,"tolerance":0.05}},{"id":"IBAI-1.2-P05","level":"Foundation","prompt":"For an arithmetic sequence with \\(u_1=120\\) and \\(d=-7\\), find \\(u_{11}\\).","answer":"\\(50\\)","solution":"Use \\(u_n=a+(n-1)d\\): \\(120+(11-1)(-7)=50\\).","marks":2,"calculator":"Mental / GDC check","command":"Calculate","hint":"","tags":["nth term"],"check":{"mode":"number","value":50,"tolerance":1e-06}},{"id":"IBAI-1.2-P06","level":"Foundation","prompt":"Find the common difference of \\(11, 17, 23, 29,\\ldots\\).","answer":"\\(6\\)","solution":"Subtract consecutive terms; every difference equals \\(6\\).","marks":2,"calculator":"Mental","command":"Find","hint":"","tags":["common difference"],"check":{"mode":"number","value":6,"tolerance":1e-06}},{"id":"IBAI-1.2-P07","level":"Foundation","prompt":"Find the common difference of \\(40, 35, 30, 25,\\ldots\\).","answer":"\\(-5\\)","solution":"Subtract consecutive terms; every difference equals \\(-5\\).","marks":2,"calculator":"Mental","command":"Find","hint":"","tags":["common difference"],"check":{"mode":"number","value":-5,"tolerance":1e-06}},{"id":"IBAI-1.2-P08","level":"Foundation","prompt":"Find the common difference of \\(-2, 1.5, 5, 8.5,\\ldots\\).","answer":"\\(3.5\\)","solution":"Subtract consecutive terms; every difference equals \\(3.5\\).","marks":2,"calculator":"Mental","command":"Find","hint":"","tags":["common difference"],"check":{"mode":"number","value":3.5,"tolerance":0.05}},{"id":"IBAI-1.2-P09","level":"Foundation","prompt":"Find the common difference of \\(0.8, 1.1, 1.4, 1.7,\\ldots\\).","answer":"\\(0.3\\)","solution":"Subtract consecutive terms; every difference equals \\(0.3\\).","marks":2,"calculator":"Mental","command":"Find","hint":"","tags":["common difference"],"check":{"mode":"number","value":0.3,"tolerance":0.05}},{"id":"IBAI-1.2-P10","level":"Foundation","prompt":"Find the common difference of \\(100, 88, 76, 64,\\ldots\\).","answer":"\\(-12\\)","solution":"Subtract consecutive terms; every difference equals \\(-12\\).","marks":2,"calculator":"Mental","command":"Find","hint":"","tags":["common difference"],"check":{"mode":"number","value":-12,"tolerance":1e-06}},{"id":"IBAI-1.2-P11","level":"Application","prompt":"Find \\(S_{20}\\) for an arithmetic sequence with \\(a=4\\), \\(d=5\\).","answer":"\\(1030\\)","solution":"First \\(u_{20}=99\\). Then \\(S_n=\\frac n2(a+u_n)=\\frac{20}2(4+99)=1030\\).","marks":3,"calculator":"GDC expected","command":"Calculate","hint":"","tags":["series"],"check":{"mode":"number","value":1030.0,"tolerance":1e-06}},{"id":"IBAI-1.2-P12","level":"Application","prompt":"Find \\(S_{16}\\) for an arithmetic sequence with \\(a=30\\), \\(d=-1.5\\).","answer":"\\(300\\)","solution":"First \\(u_{16}=7.5\\). Then \\(S_n=\\frac n2(a+u_n)=\\frac{16}2(30+7.5)=300\\).","marks":3,"calculator":"GDC expected","command":"Calculate","hint":"","tags":["series"],"check":{"mode":"number","value":300.0,"tolerance":1e-06}},{"id":"IBAI-1.2-P13","level":"Application","prompt":"Find \\(S_{25}\\) for an arithmetic sequence with \\(a=12\\), \\(d=7\\).","answer":"\\(2400\\)","solution":"First \\(u_{25}=180\\). Then \\(S_n=\\frac n2(a+u_n)=\\frac{25}2(12+180)=2400\\).","marks":3,"calculator":"GDC expected","command":"Calculate","hint":"","tags":["series"],"check":{"mode":"number","value":2400.0,"tolerance":1e-06}},{"id":"IBAI-1.2-P14","level":"Application","prompt":"Find \\(S_{30}\\) for an arithmetic sequence with \\(a=2.4\\), \\(d=0.6\\).","answer":"\\(333\\)","solution":"First \\(u_{30}=19.8\\). Then \\(S_n=\\frac n2(a+u_n)=\\frac{30}2(2.4+19.8)=333\\).","marks":3,"calculator":"GDC expected","command":"Calculate","hint":"","tags":["series"],"check":{"mode":"number","value":332.99999999999994,"tolerance":1e-06}},{"id":"IBAI-1.2-P15","level":"Application","prompt":"Find \\(S_{28}\\) for an arithmetic sequence with \\(a=150\\), \\(d=-4\\).","answer":"\\(2688\\)","solution":"First \\(u_{28}=42\\). Then \\(S_n=\\frac n2(a+u_n)=\\frac{28}2(150+42)=2688\\).","marks":3,"calculator":"GDC expected","command":"Calculate","hint":"","tags":["series"],"check":{"mode":"number","value":2688.0,"tolerance":1e-06}},{"id":"IBAI-1.2-P16","level":"Application","prompt":"A theatre has 24 seats in the first row and 3 more seats in each later row. Find the number of seats in row 18.","answer":"\\(75\\)","solution":"Use \\(u_{18}=24+17(3)=75\\).","marks":3,"calculator":"GDC expected","command":"Calculate","hint":"","tags":["context"],"check":{"mode":"number","value":75,"tolerance":1e-06}},{"id":"IBAI-1.2-P17","level":"Application","prompt":"A theatre has 24 seats in the first row and 3 more seats in each later row. There are 18 rows. Find the total number of seats.","answer":"\\(891\\)","solution":"Use \\(S_{18}=9(24+75)=891\\).","marks":3,"calculator":"GDC expected","command":"Calculate","hint":"","tags":["context"],"check":{"mode":"number","value":891.0,"tolerance":1e-06}},{"id":"IBAI-1.2-P18","level":"Application","prompt":"A runner completes 2.0 km in week 1 and increases the weekly distance by 0.75 km. Find the distance in week 14.","answer":"\\(11.75\\)","solution":"\\(u_{14}=2+13(0.75)=11.75\\) km.","marks":3,"calculator":"GDC expected","command":"Calculate","hint":"","tags":["context"],"check":{"mode":"number","value":11.75,"tolerance":0.05}},{"id":"IBAI-1.2-P19","level":"Application","prompt":"A water tank contains 600 L at time 0 and loses 18 L per minute. Find the amount after 23 minutes.","answer":"\\(186\\)","solution":"With time indexed from 0, \\(V(t)=600-18t\\), so \\(V(23)=186\\) L.","marks":3,"calculator":"GDC expected","command":"Calculate","hint":"","tags":["context"],"check":{"mode":"number","value":186,"tolerance":1e-06}},{"id":"IBAI-1.2-P20","level":"Application","prompt":"A student saves QAR 50 in month 1 and QAR 8 more each later month. Find the total saved in the first 12 months.","answer":"\\(1128\\)","solution":"\\(S_{12}=6[100+88]=1128\\) QAR.","marks":3,"calculator":"GDC expected","command":"Calculate","hint":"","tags":["context"],"check":{"mode":"number","value":1128.0,"tolerance":1e-06}},{"id":"IBAI-1.2-P21","level":"Reasoning","prompt":"An arithmetic sequence has \\(u_6=31\\) and \\(u_{15}=76\\). Find \\(d\\).","answer":"\\(5\\)","solution":"Subtract equations: \\(9d=45\\), so \\(d=5\\).","marks":3,"calculator":"GDC expected","command":"Calculate","hint":"","tags":["reverse reasoning"],"check":{"mode":"number","value":5,"tolerance":1e-06}},{"id":"IBAI-1.2-P22","level":"Reasoning","prompt":"An arithmetic sequence has \\(u_6=31\\) and \\(u_{15}=76\\). Find \\(u_1\\).","answer":"\\(6\\)","solution":"\\(a+5(5)=31\\), so \\(a=6\\).","marks":3,"calculator":"GDC expected","command":"Calculate","hint":"","tags":["reverse reasoning"],"check":{"mode":"number","value":6,"tolerance":1e-06}},{"id":"IBAI-1.2-P23","level":"Reasoning","prompt":"An arithmetic sequence has \\(u_4=18\\) and \\(u_{10}=42\\). Find \\(u_{25}\\).","answer":"\\(102\\)","solution":"\\(6d=24\\Rightarrow d=4\\), \\(a=6\\), so \\(u_{25}=102\\).","marks":3,"calculator":"GDC expected","command":"Calculate","hint":"","tags":["reverse reasoning"],"check":{"mode":"number","value":102,"tolerance":1e-06}},{"id":"IBAI-1.2-P24","level":"Reasoning","prompt":"Which term of \\(7,12,17,\\ldots\\) is 102?","answer":"\\(20\\)","solution":"Solve \\(7+(n-1)5=102\\), giving \\(n=20\\).","marks":3,"calculator":"GDC expected","command":"Calculate","hint":"","tags":["reverse reasoning"],"check":{"mode":"number","value":20,"tolerance":1e-06}},{"id":"IBAI-1.2-P25","level":"Reasoning","prompt":"How many positive terms are in \\(85,78,71,\\ldots\\)?","answer":"\\(13\\)","solution":"Solve \\(85-7(n-1)>0\\). This gives \\(n<13.142\\ldots\\), so 13 positive terms.","marks":3,"calculator":"GDC expected","command":"Calculate","hint":"","tags":["reverse reasoning"],"check":{"mode":"number","value":13,"tolerance":1e-06}},{"id":"IBAI-1.2-P26","level":"Reasoning","prompt":"The sum of the first \\(n\\) terms of \\(3,7,11,\\ldots\\) is 528. Find \\(n\\).","answer":"\\(16\\)","solution":"\\(S_n=\\frac n2[6+4(n-1)]=n(2n+1)=528\\). Solving gives \\(n=16\\).","marks":3,"calculator":"GDC expected","command":"Calculate","hint":"","tags":["reverse reasoning"],"check":{"mode":"number","value":16,"tolerance":1e-06}},{"id":"IBAI-1.2-P27","level":"Reasoning","prompt":"Insert three arithmetic means between 8 and 28. Find the second inserted mean.","answer":"\\(18\\)","solution":"There are 4 equal gaps, so \\(d=(28-8)/4=5\\). The inserted values are 13,18,23.","marks":3,"calculator":"GDC expected","command":"Calculate","hint":"","tags":["reverse reasoning"],"check":{"mode":"number","value":18,"tolerance":1e-06}},{"id":"IBAI-1.2-P28","level":"Reasoning","prompt":"A sequence has \\(S_{20}=860\\) and \\(a=5\\). Find \\(d\\).","answer":"\\(4\\)","solution":"\\(860=10[10+19d]\\Rightarrow86=10+19d\\Rightarrow d=4\\).","marks":3,"calculator":"GDC expected","command":"Calculate","hint":"","tags":["reverse reasoning"],"check":{"mode":"number","value":4,"tolerance":1e-06}},{"id":"IBAI-1.2-P29","level":"Reasoning","prompt":"The tenth term is twice the fourth term and \\(a=6\\). Find \\(d\\).","answer":"\\(2\\)","solution":"\\(6+9d=2(6+3d)\\Rightarrow3d=6\\Rightarrow d=2\\).","marks":3,"calculator":"GDC expected","command":"Calculate","hint":"","tags":["reverse reasoning"],"check":{"mode":"number","value":2,"tolerance":1e-06}},{"id":"IBAI-1.2-P30","level":"Reasoning","prompt":"The arithmetic sequence rules are \\(u_n=4n+3\\) and \\(v_n=70-3n\\). Solve \\(u_n=v_n\\) for real \\(n\\).","answer":"\\(9.571429\\)","solution":"Solve \\(4n+3=70-3n\\), so \\(n=67/7\\). Therefore no integer-indexed term is shared at the same index.","marks":3,"calculator":"GDC expected","command":"Calculate","hint":"","tags":["reverse reasoning"],"check":{"mode":"number","value":9.571428571428571,"tolerance":0.005}},{"id":"IBAI-1.2-P31","level":"Challenge","prompt":"A stadium section has 32 seats in row 1 and 4 more per row. What is the greatest number of complete rows possible if the section can hold at most 1800 seats?","answer":"\\(23\\)","solution":"Solve \\(2n(n+15)\\le1800\\). The positive boundary is about 23.42, so the greatest complete number of rows is 23.","marks":4,"calculator":"GDC expected","command":"Calculate","hint":"","tags":["challenge","modelling"],"check":{"mode":"number","value":23,"tolerance":1e-06}},{"id":"IBAI-1.2-P32","level":"Challenge","prompt":"An arithmetic sequence has \\(u_3+u_8=34\\) and \\(u_{12}=43\\). Find \\(u_1\\).","answer":"\\(-1\\)","solution":"\\(2a+9d=34\\) and \\(a+11d=43\\). These give \\(d=4\\), then \\(a=-1\\).","marks":4,"calculator":"GDC expected","command":"Calculate","hint":"","tags":["challenge","modelling"],"check":{"mode":"number","value":-1,"tolerance":1e-06}},{"id":"IBAI-1.2-P33","level":"Challenge","prompt":"A sequence has \\(S_n=3n^2+2n\\). Find \\(u_{20}\\).","answer":"\\(119\\)","solution":"\\(u_n=S_n-S_{n-1}=6n-1\\); hence \\(u_{20}=119\\).","marks":4,"calculator":"GDC expected","command":"Calculate","hint":"","tags":["challenge","modelling"],"check":{"mode":"number","value":119,"tolerance":1e-06}},{"id":"IBAI-1.2-P34","level":"Challenge","prompt":"A company produces 120 units in month 1 and 15 more each month. In which month does cumulative production first exceed 5000 units?","answer":"\\(20\\)","solution":"\\(S_{19}=4845\\le5000\\), while \\(S_{20}=5250>5000\\).","marks":4,"calculator":"GDC expected","command":"Calculate","hint":"","tags":["challenge","modelling"],"check":{"mode":"number","value":20,"tolerance":1e-06}},{"id":"IBAI-1.2-P35","level":"Challenge","prompt":"A staircase has 15 blocks in the first layer and 2 fewer in each successive layer. If all layers are positive, find the total blocks.","answer":"\\(64\\)","solution":"Terms are 15,13,11,9,7,5,3,1: 8 terms, sum \\(8(15+1)/2=64\\).","marks":4,"calculator":"GDC expected","command":"Calculate","hint":"","tags":["challenge","modelling"],"check":{"mode":"number","value":64,"tolerance":1e-06}},{"id":"IBAI-1.2-P36","level":"Challenge","prompt":"Three consecutive terms of an arithmetic sequence sum to 72 and their product is 13,680. Find the middle term.","answer":"\\(24\\)","solution":"Consecutive terms are \\(24-d,24,24+d\\). Their product gives \\(24(576-d^2)=13680\\Rightarrow d^2=6\\); the middle term is 24.","marks":4,"calculator":"GDC expected","command":"Calculate","hint":"","tags":["challenge","modelling"],"check":{"mode":"number","value":24,"tolerance":1e-06}},{"id":"IBAI-1.2-P37","level":"Challenge","prompt":"A linear subscription costs QAR 150 initially and rises QAR 12 each year. Find the total paid over 10 years.","answer":"\\(2040\\)","solution":"Payments form an arithmetic series: \\(S_{10}=5[300+108]=2040\\).","marks":4,"calculator":"GDC expected","command":"Calculate","hint":"","tags":["challenge","modelling"],"check":{"mode":"number","value":2040,"tolerance":1e-06}},{"id":"IBAI-1.2-P38","level":"Challenge","prompt":"A sequence begins at 250 and decreases by 9. Find the sum of all positive terms.","answer":"\\(3598\\)","solution":"The last positive term is 7 at \\(n=28\\). Thus \\(S_{28}=14(250+7)=3598\\).","marks":4,"calculator":"GDC expected","command":"Calculate","hint":"","tags":["challenge","modelling"],"check":{"mode":"number","value":3598,"tolerance":1e-06}},{"id":"IBAI-1.2-P39","level":"Challenge","prompt":"The 7th term is 29 and the sum of the first 15 terms is 495. Find the common difference.","answer":"\\(4\\)","solution":"\\(a+6d=29\\) and \\(495=\\frac{15}{2}(2a+14d)=15(a+7d)\\), so \\(a+7d=33\\). Hence \\(d=4\\).","marks":4,"calculator":"GDC expected","command":"Calculate","hint":"","tags":["challenge","modelling"],"check":{"mode":"number","value":4,"tolerance":1e-06}},{"id":"IBAI-1.2-P40","level":"Challenge","prompt":"A freelancer earns QAR 900 in week 1 and increases weekly earnings by QAR 60. Find the first week in which total earnings exceed QAR 20,000.","answer":"\\(16\\)","solution":"\\(S_{16}=21600\\), while \\(S_{15}=19800\\); therefore week 16 is the first to exceed QAR 20,000.","marks":4,"calculator":"GDC expected","command":"Calculate","hint":"","tags":["challenge","modelling"],"check":{"mode":"number","value":16,"tolerance":1e-06}}],"quiz":[{"id":"IBAI-1.2-Q01","level":"Quiz","prompt":"For \\(a=9,d=4\\), find \\(u_{17}\\).","answer":"\\(73\\)","solution":"\\(9+16(4)=73\\).","marks":2,"calculator":"GDC expected","command":"Calculate","hint":"","tags":["quiz"],"check":{"mode":"number","value":73,"tolerance":1e-06}},{"id":"IBAI-1.2-Q02","level":"Quiz","prompt":"Find the common difference of \\(42,36,30,\\ldots\\).","answer":"\\(-6\\)","solution":"Subtract consecutive terms.","marks":2,"calculator":"GDC expected","command":"Calculate","hint":"","tags":["quiz"],"check":{"mode":"number","value":-6,"tolerance":1e-06}},{"id":"IBAI-1.2-Q03","level":"Quiz","prompt":"For \\(a=5,d=3\\), find \\(S_{20}\\).","answer":"\\(670\\)","solution":"\\(u_{20}=62\\), so \\(S_{20}=10(67)=670\\).","marks":2,"calculator":"GDC expected","command":"Calculate","hint":"","tags":["quiz"],"check":{"mode":"number","value":670,"tolerance":1e-06}},{"id":"IBAI-1.2-Q04","level":"Quiz","prompt":"Given \\(u_4=22\\) and \\(u_{11}=57\\), find \\(d\\).","answer":"\\(5\\)","solution":"\\(7d=35\\).","marks":2,"calculator":"GDC expected","command":"Calculate","hint":"","tags":["quiz"],"check":{"mode":"number","value":5,"tolerance":1e-06}},{"id":"IBAI-1.2-Q05","level":"Quiz","prompt":"Which term of \\(8,13,18,\\ldots\\) is 103?","answer":"\\(20\\)","solution":"Solve \\(8+5(n-1)=103\\).","marks":2,"calculator":"GDC expected","command":"Calculate","hint":"","tags":["quiz"],"check":{"mode":"number","value":20,"tolerance":1e-06}},{"id":"IBAI-1.2-Q06","level":"Quiz","prompt":"A row has 18 seats and each later row has 2 more. Find seats in row 25.","answer":"\\(66\\)","solution":"\\(18+24(2)=66\\).","marks":2,"calculator":"GDC expected","command":"Calculate","hint":"","tags":["quiz"],"check":{"mode":"number","value":66,"tolerance":1e-06}},{"id":"IBAI-1.2-Q07","level":"Quiz","prompt":"Find total seats in the first 25 rows of that pattern.","answer":"\\(1050\\)","solution":"\\(S_{25}=25(18+66)/2=1050\\).","marks":2,"calculator":"GDC expected","command":"Calculate","hint":"","tags":["quiz"],"check":{"mode":"number","value":1050,"tolerance":1e-06}},{"id":"IBAI-1.2-Q08","level":"Quiz","prompt":"Insert four arithmetic means between 10 and 40. Find the common difference.","answer":"\\(6\\)","solution":"There are five equal intervals: \\((40-10)/5=6\\).","marks":2,"calculator":"GDC expected","command":"Calculate","hint":"","tags":["quiz"],"check":{"mode":"number","value":6,"tolerance":1e-06}},{"id":"IBAI-1.2-Q09","level":"Quiz","prompt":"A sequence has \\(S_n=2n^2+3n\\). Find \\(u_{12}\\).","answer":"\\(49\\)","solution":"\\(u_n=S_n-S_{n-1}=4n+1\\).","marks":3,"calculator":"GDC expected","command":"Calculate","hint":"","tags":["quiz"],"check":{"mode":"number","value":49,"tolerance":1e-06}},{"id":"IBAI-1.2-Q10","level":"Quiz","prompt":"A payment starts at QAR 200 and rises QAR 15 yearly. Find the total over 8 years.","answer":"\\(2020\\)","solution":"\\(S_8=4[400+105]=2020\\).","marks":3,"calculator":"GDC expected","command":"Calculate","hint":"","tags":["quiz"],"check":{"mode":"number","value":2020,"tolerance":1e-06}}],"exam":[{"id":"IBAI-1.2-E01","style":"Paper 1-style short response","title":"Auditorium seating","calculator":"GDC expected","total_marks":9,"context":"An auditorium has 28 seats in the first row and 3 additional seats in every later row. There are 24 rows.","parts":[{"label":"a","prompt":"Write a formula for the number of seats in row \\(n\\).","marks":2,"answer":"\\(u_n=28+3(n-1)=3n+25\\)","markscheme":"M1 arithmetic nth-term structure; A1 simplified/equivalent formula."},{"label":"b","prompt":"Find the number of seats in the final row.","marks":2,"answer":"97","markscheme":"M1 substitutes \\(n=24\\); A1 97."},{"label":"c","prompt":"Find the total number of seats.","marks":3,"answer":"1500","markscheme":"M1 uses arithmetic sum; M1 substitutes endpoints; A1 1500."},{"label":"d","prompt":"The design allows at most 1600 seats. State whether one additional row following the pattern is possible. Justify.","marks":2,"answer":"Yes. Row 25 has 100 seats, so the new total is exactly 1600.","markscheme":"M1 computes row 25 or the new total; A1 concludes that equality is allowed by “at most”."}]},{"id":"IBAI-1.2-E02","style":"Paper 2-style extended response","title":"Water-tank monitoring","calculator":"GDC expected","total_marks":11,"context":"At time \\(t=0\\), a tank contains 920 L. During a controlled release it loses 17 L each minute.","parts":[{"label":"a","prompt":"Write a model for volume \\(V_t\\) after \\(t\\) minutes.","marks":2,"answer":"\\(V_t=920-17t\\)","markscheme":"M1 identifies constant decrease; A1 model with correct initial indexing."},{"label":"b","prompt":"Find the volume after 31 minutes.","marks":2,"answer":"393 L","markscheme":"M1 substitutes 31; A1 393."},{"label":"c","prompt":"Find the first whole minute at which the volume is below 250 L.","marks":3,"answer":"40 minutes","markscheme":"M1 solves \\(920-17t<250\\); A1 threshold \\(t>39.411...\\); A1 first integer 40."},{"label":"d","prompt":"Find the total amount recorded if readings at minutes 0 through 20 are added.","marks":3,"answer":"15,750 L","markscheme":"M1 recognizes 21 terms; M1 uses endpoints 920 and 580; A1 \\(21(1500)/2=15750\\)."},{"label":"e","prompt":"State one reason the linear model cannot continue indefinitely.","marks":1,"answer":"It eventually predicts negative volume or ignores changing flow conditions.","markscheme":"A1 relevant limitation."}]}],"bankBridge":{"course":"ib-math-ai","unit":1,"lesson":"1.2","skillKeys":["IBAI.U1.SEQUENCES","IBAI.U1.MODELING"],"visibility":"authenticated-school-access","embeddedPrivatePrompts":false},"assessmentDesign":{"practiceLevels":{"Foundation":10,"Application":10,"Reasoning":10,"Challenge":10},"quizQuestions":10,"extendedTasks":2,"calculatorPolicy":"Technology is integrated throughout, with transparent setup and interpretation."}};
